<script setup>
import {computed,reactive} from 'vue';
import {backgroundModes,normalizeBackground,patternField} from '../sceneBackground.js';
import NumberRange from './NumberRange.vue';
import AnimationKeyButton from './AnimationKeyButton.vue';
import PaletteColor from './PaletteColor.vue';
const props=defineProps({studio:Object}),s=reactive(props.studio);
const shared=computed(()=>s.application==='slides'&&s.frame.fixedBackground);
const b=computed(()=>normalizeBackground(shared.value?s.frame.background:s.isAnimation?s.animation.evaluate().scene.background:s.current.background));
function replace(value){if(shared.value)s.frame.background=value;else s.current.background=value;}
function toggleShared(event){if(event.target.checked&&(!s.frame.background||s.frame.background.mode==='inherit'))s.frame.background=normalizeBackground(s.current.background);s.frame.fixedBackground=event.target.checked;}
function set(field,value){if(s.isAnimation){const channel=patternField(field);if(channel)s.animation.setProperty(channel,field==='mode'?backgroundModes.findIndex(([id])=>id===value):field==='stagger'?Number(value):value);return;}replace({...b.value,[field]:value});}
const colors=computed(()=>new Proxy(b.value,{set(_,field,value){set(field,value);return true;}}));
const presets=[['Sombre à points','#101820','#ffffff','dots'],['Papier à points','#faf9f6','#182126','dots'],['Grille technique','#101820','#7dcbb8','grid'],['Lignes obliques','#f5f4f0','#405568','lines']];
function preset(p){const value=normalizeBackground({mode:p[3],base:p[1],color:p[2],opacity:18,rotation:p[3]==='lines'?35:0});if(!s.isAnimation){replace(value);return;}s.animation.beginGesture();try{for(const [field,v] of Object.entries(value)){const channel=patternField(field);if(channel)s.animation.setProperty(channel,field==='mode'?backgroundModes.findIndex(([id])=>id===v):field==='stagger'?Number(v):v,false,false);}}finally{s.animation.endGesture();}}
</script>
<template><div class="background-properties"><label v-if="s.application==='slides'" class="checkbox-label"><input type="checkbox" :checked="shared" @change="toggleShared">Fond commun fixe sur toutes les diapos</label><p v-if="shared" class="field-help">Seuls les objets se déplacent pendant les transitions. Ces réglages s’appliquent à tout le diaporama.</p><p class="field-help">{{shared?'Fond partagé':'Fond de cette composition'}}, conservé dans les exports. Les calques opaques placés devant peuvent le masquer.</p><div class="background-presets"><button v-for="p in presets" :key="p[0]" :title="p[0]" :aria-label="p[0]" @click="preset(p)"><span :style="{backgroundColor:p[1],color:p[2]}">⠿</span>{{p[0]}}</button></div><label>Type de fond<AnimationKeyButton v-if="s.isAnimation" :studio="s" field="patternMode"/><select aria-label="Type de fond" :value="b.mode" @change="set('mode',$event.target.value)"><option v-for="[id,label] in backgroundModes" :key="id" :value="id">{{label}}</option></select></label><template v-if="!['inherit','transparent'].includes(b.mode)"><PaletteColor :element="colors" field="base" label="Couleur du fond" :theme="s.theme"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('base')"/></template></PaletteColor><PaletteColor v-if="b.mode==='gradient'" :element="colors" field="color2" label="Deuxième couleur" :theme="s.theme"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('color2')"/></template></PaletteColor><template v-if="!['solid','gradient'].includes(b.mode)"><PaletteColor :element="colors" field="color" label="Couleur du motif" :theme="s.theme"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('color')"/></template></PaletteColor><NumberRange label="Opacité du motif" unit="%" :model-value="b.opacity" @update:model-value="set('opacity',$event)"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('opacity')"/></template></NumberRange><NumberRange v-if="!['grid','lines'].includes(b.mode)" label="Taille du motif" unit="px" :min="1" :max="100" :model-value="b.size" @update:model-value="set('size',$event)"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('size')"/></template></NumberRange><NumberRange label="Espacement du motif" unit="px" :min="8" :max="240" :model-value="b.spacing" @update:model-value="set('spacing',$event)"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('spacing')"/></template></NumberRange><NumberRange v-if="['grid','lines','crosses','hexagons'].includes(b.mode)" label="Épaisseur du motif" unit="px" :min="0.5" :max="12" :step="0.5" :model-value="b.thickness" @update:model-value="set('thickness',$event)"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('thickness')"/></template></NumberRange><label v-if="!['grid','lines'].includes(b.mode)" class="checkbox-label"><input type="checkbox" :checked="b.stagger" @change="set('stagger',$event.target.checked)">Disposition en quinconce<AnimationKeyButton v-if="s.isAnimation" :studio="s" field="patternStagger"/></label><NumberRange v-for="[field,label] in [['offsetX','Décalage horizontal'],['offsetY','Décalage vertical']]" :key="field" :label="label" unit="px" :min="-240" :max="240" :model-value="b[field]" @update:model-value="set(field,$event)"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField(field)"/></template></NumberRange></template><NumberRange v-if="b.mode!=='solid'" label="Rotation du fond" unit="°" :min="-180" :max="180" :model-value="b.rotation" @update:model-value="set('rotation',$event)"><template v-if="s.isAnimation" #actions><AnimationKeyButton :studio="s" :field="patternField('rotation')"/></template></NumberRange></template></div></template>
<style scoped>
.background-properties{display:grid;gap:14px}.background-properties :deep(label){margin-top:0}.background-properties>.field-help{margin:0}.background-presets{display:grid;grid-template-columns:1fr 1fr;gap:6px}.background-presets button{display:flex;align-items:center;gap:7px;text-align:left;border:1px solid var(--border);border-radius:7px;padding:7px;background:transparent;color:inherit;font:inherit;font-size:11px;cursor:pointer}.background-presets button:hover{border-color:var(--mint)}.background-presets span{display:grid;place-items:center;border-radius:4px;width:28px;height:28px;flex-shrink:0;font-size:24px}
</style>
